// SpecFor returns a resource's spec by command_name.
func SpecFor(resource string) (ResourceSpec, bool) {
	for _, r := range ResourceSpecs {
		if r.Command == resource {
			return r, true
		}
	}
	return ResourceSpec{}, false
}

// ActionSpecFor returns a resource action's spec by command_names.
func ActionSpecFor(resource, action string) (ActionSpec, bool) {
	r, ok := SpecFor(resource)
	if !ok {
		return ActionSpec{}, false
	}
	for _, a := range r.Actions {
		if a.Command == action {
			return a, true
		}
	}
	return ActionSpec{}, false
}
